import open from "open";

const dbPath = path.resolve(__dirname, "../kmap.json");

type DB = Record<
  string,
  { name: string; description: string; deps: string[]; color?: string }
>;

const kMapToDotFile = (db: DB) => {
  const deepDependencies = getDeepDependencies(db);
  return `
  digraph kmap {
    ${Object.values(db)
      .map((node) => {
        return `
        ${node.color ? `"${node.name}" [color=${node.color}]` : ``}
        ${node.deps
          .filter((dep) => {
            return !deepDependencies[node.name]?.[dep];
          })
          .map((dep) => {
            return `"${dep}" -> "${node.name}"`;
          })
          .join("\n")}`;
      })
      .join("\n")}
  }
  `;
};

export const dotfile = async () => {
  const db = await fs.readFile(dbPath, "utf8");

  const dotfile = kMapToDotFile(JSON.parse(db));

  open(
    `https://dreampuf.github.io/GraphvizOnline/#${encodeURIComponent(dotfile)}`,
  );
};

const getDeepDependencies = (db: DB): Record<string, Record<string, true>> => {
  const deps: Record<string, Record<string, true>> = {};

  const getDeepDepsOfEntry = (
    deps: string[],
    depSet = new Set<string>(),
    depth = 0,
  ) => {
    if (depth > 0) {
      deps.forEach((dep) => {
        depSet.add(dep);
      });
    }
    deps.forEach((dep) => {
      if (!db[dep]) {
        return;
      }
      getDeepDepsOfEntry(db[dep].deps, depSet, depth + 1);
    });
    return depSet;
  };

  Object.values(db).forEach((entry) => {
    const depSet = getDeepDepsOfEntry(entry.deps);

    deps[entry.name] = {};

    Array.from(depSet).forEach((dep) => {
      deps[entry.name][dep] = true;
    });
  });

  return deps;
};

export const kmap = async () => {
  while (true) {
    let db = JSON.parse(await fs.readFile(dbPath, "utf8"));
    // Which node do you want to add?

    const { node } = await prompts({
      name: "node",
      type: "text",
      message: "What is the name of the node you want to add?",
    });

    if (!node) break;

    // // Add a description for that node

    // const { description } = await prompts({
    //   name: "description",
    //   type: "text",
    //   message: "What is the description of the node you want to add?",
    // });

    // Which dependencies does this node have?

    let deps: string[] = [];

    if (Object.values(db).length > 0) {
      const result = await prompts({
        name: "deps",
        type: "autocompleteMultiselect",
        message: "Which dependencies do you want to add?",
        choices: Object.keys(db).map((name) => ({ title: name, value: name })),
      });
      if (!result.deps || result.deps.length === 0) break;
      deps = result.deps;
    }

    db = JSON.parse(await fs.readFile(dbPath, "utf8"));

    // Add the node to the database

    db[node] = {
      name: node,
      description: "",
      deps,
    };

    await fs.writeFile(dbPath, JSON.stringify(db, null, 2));
  }
};

import { exec } from "./exec";
import { assign, createMachine, interpret } from "xstate";
import prompts from "prompts";
import { execSync } from "child_process";
import { makePromptService } from "./makePromptService";

interface Context {
  issueName?: string;
  prTitle?: string;
  currentBranch?: string;
  isDraft: boolean;
  loomLink?: string;
  reviewers: string[];
}

type Event =
  | {
      type: "HAS_NO_STAGED_CHANGES";
    }
  | {
      type: "UNSTAGE_CHANGE_CHECK_COMPLETE";
    };

function fixBranchName(branchName: string): string {
  const regex = /[^a-zA-Z0-9._-]/g; // Match any character that is NOT alphanumeric, period, underscore, or hyphen
  const cleanedName = branchName.replace(regex, "-"); // Replace any non-matching characters with a hyphen
  return cleanedName.toLowerCase();
}

const machine = createMachine<Context, Event>({
  initial: "checkingIfHasGithubCliInstalled",
  context: {
    isDraft: false,
    reviewers: [],
  },
  states: {
    checkingIfHasGithubCliInstalled: {
      invoke: {
        src: async () => {
          execSync("gh --version", {
            stdio: "ignore",
          });
        },
        onDone: {
          target: "checkingIfHasUnstagedChanges",
        },
        onError: {
          target: "#complete",
          actions: () => console.log("You must have GitHub CLI installed."),
        },
      },
    },
    checkingIfHasUnstagedChanges: {
      on: {
        HAS_NO_STAGED_CHANGES: {
          target: "#complete",
          actions: () => {
            console.error(
              "You have no staged changes. Cannot create a new branch.",
            );
          },
        },
        UNSTAGE_CHANGE_CHECK_COMPLETE: {
          target: "gettingCurrentBranch",
        },
      },
      invoke: {
        src: () => async (send) => {
          const hasStagedChanges =
            execSync(`git diff --cached`).toString().length > 0;

          if (!hasStagedChanges) {
            const { runGitAdd } = await prompts({
              name: "runGitAdd",
              type: "confirm",
              message:
                "You currently have no staged changes ready for commit. Would you like us to stage all changes?",
            });

            if (!runGitAdd) {
              return send("HAS_NO_STAGED_CHANGES");
            }

            exec(`git add .`);

            const hasStagedChangesAfterAdd =
              execSync(`git diff --cached`).toString().length > 0;

            if (!hasStagedChangesAfterAdd) {
              return send("HAS_NO_STAGED_CHANGES");
            }
          }

          return send("UNSTAGE_CHANGE_CHECK_COMPLETE");
        },
      },
    },
    gettingCurrentBranch: {
      always: {
        target: "gettingIssueNameAndMessage",
        actions: assign((context, event) => {
          const branchName = execSync(
            "echo $(git symbolic-ref --short -q HEAD)",
          )
            .toString()
            .trim();

          return {
            currentBranch: branchName,
          };
        }),
      },
    },
    gettingIssueNameAndMessage: {
      onDone: {
        target: "creatingAndPushingBranch",
      },
      initial: "askingForPrTitle",
      states: {
        askingForPrTitle: {
          invoke: makePromptService(
            [
              {
                name: "title",
                type: "text",
                message: `What is the title of this PR?`,
              },
              {
                name: "isDraft",
                type: "confirm",
                message: "Is this PR a draft?",
              },
              {
                name: "loomLink",
                type: "text",
                message: "Provide a loom link for the PR:",
              },
            ],
            {
              onDone: [
                {
                  cond: (ctx, e) => e.data.title,
                  actions: assign({
                    prTitle: (context, event) => {
                      return event.data.title;
                    },
                    issueName: (context, event) => {
